import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"泽天夬","description":"周易折中 - 泽天夬","frontmatter":{"title":"泽天夬","description":"周易折中 - 泽天夬"},"headers":[],"relativePath":"zh/classics/zhezhong/049.md","filePath":"zh/classics/zhezhong/049.md"}'),h={name:"zh/classics/zhezhong/049.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="泽天夬" tabindex="-1">泽天夬 <a class="header-anchor" href="#泽天夬" aria-label="Permalink to “泽天夬”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈夬序卦〉：“益而不已必决，故受之以夬。夬者，决也。益之极必决而后止，理无常益，益而不已，已乃决也。夬所以次益也。为卦兑上干下，以二体言之，泽水之聚也，乃上于至高之处，有溃决之象。以爻言之，五阳在下，长而将极，一阴在上，消而将尽，众阳上进，决去一阴，所以为夬也。夬者，刚决之义，众阳进而决去一阴，君子道长，小人消衰将尽之时也。”</p><p>夬：扬于王庭，孚号有厉，告自邑，不利即戎，利有攸往</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>夬，决也。阳决阴也。三月之卦也。以五阳去一阴，决之而已。然其决之也，必正名其罪而尽诚以呼号其众，相与合力。然亦尚有危厉，不可安肆，又当先治其私，而不可专尚威武。则利有所往也，皆戒之之辞。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>小人方盛之时，君子之道未胜，安能显然以正道决去之？故含晦俟时，渐图消之之道。今既小人衰微，君子道盛，当显行之于公朝，使人明知善恶。故云“扬于王庭”，孚信之在中，诚意也。号者，命众之辞。君子之道虽长盛，而不敢忘戒备，故至诚以命众，使知尚有危道。虽以此之甚盛决彼之甚衰，若易而无备，则有不虞之悔，是尚有危理，必有戒惧之心，则无患也。圣人设戒之意深矣。君子之治小人，以其不善也，必以己之善道胜之。革之故，圣人诛乱必先脩己，舜之敷文徳是也。邑，私邑。“告自邑”，先自治也。以众阳之盛决于一阴，力固有馀，然不可极其刚至于太过，太过乃如䝉上九之为寇也。戎兵者，强武之事。“不利即戎”，谓不宜尚壮武也。即从也，“从戎”尚武也。“利有攸往”，阳虽盛未极乎上，阴虽微犹有未去，是小人尚有存者，君子之道有未至也，故宜进而往也。不尚刚武而其道益进，乃夬之善也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>游氏酢曰 ：扬于王庭，诵言于上也。孚号，诞告于下也。告自邑，自近而及远也。</li></ul><p>游氏酢曰 ：扬于王庭，诵言于上也。孚号，诞告于下也。告自邑，自近而及远也。</p><ul><li>胡氏炳文曰 ：以五阳去一阴，而彖为警戒危惧之辞不一。盖必扬于王庭，使小人之罪明，以至诚呼号其众，使君子之类合，不可以小人之衰而遂安肆也。有危道焉，不可以君子之盛而事威武也，有自治之道焉。复利往往而为临、为泰、为夬也。夬利往往而为干也。盖阴之势虽微蔓，或可滋穷或为敌，君子固无时不戒惧，尤不可于小人道衰之时忘戒惧也。</li></ul><p>胡氏炳文曰 ：以五阳去一阴，而彖为警戒危惧之辞不一。盖必扬于王庭，使小人之罪明，以至诚呼号其众，使君子之类合，不可以小人之衰而遂安肆也。有危道焉，不可以君子之盛而事威武也，有自治之道焉。复利往往而为临、为泰、为夬也。夬利往往而为干也。盖阴之势虽微蔓，或可滋穷或为敌，君子固无时不戒惧，尤不可于小人道衰之时忘戒惧也。</p><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>以彖传观之，则“扬于王庭”者，声罪正辞也；“孚号有厉”者，警戒危惧也。有厉不指时事，谓其心之忧危也。夫既曰“扬于王庭”矣，则所宣告者众，而治之务于武断矣。而又曰“告自邑，不利即戎”，意似相反，何也？曰：虽宣告者众，而其本则在于自脩；虽治之贵刚，而神武则存乎不杀也。盖“告自邑，不利即戎”是终“孚号有厉”之意，“利有攸往”是终“扬于王庭”之意。</p><p>象曰：泽上于天夬，君子以施禄及下，居德则忌</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>泽上于天，溃决之势也。施禄及下，溃决之意也。居德则忌，未详。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>泽水之聚也，而上于天至髙之处，故为夬象。君子观泽决于上而注漑于下之象，则以施禄及下，谓施其禄泽以及于下也。观其决溃之象，则以居德则忌。居德谓安处其德，则约也。忌，防也。谓约立防禁，有防禁则无溃散也。王弼作“明忌”，亦通。不云“泽在天上”，而云“泽上于天”，上于天则意不安而有决溃之势。云“在天上”，乃安辞也。案泽上于天，所谓稽天之浸也，必溃决无疑矣。财聚而不散，则悖出，故君子以施禄及下。居身无所畏忌，则满而溢，故君子之居德也，则常存畏忌而已。《礼》曰“积而能散”，《书》曰“敬忌而罔有择言在躬”，夫如是，则何溃决之患之有？</p><p>彖曰：夬，决也，刚决柔也，健而说，决而和</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>释卦名义而赞其德。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>夬为决义，五阳决上之一阴也。健而说，决而和，以二体言卦才也。下健而上说，是健而能说，决而能和，决之至善也。兑说为和。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li>何氏楷曰 ：君子以天下万物为一体，如阳德之无所不及，其于小人未尝仇视而物畜之也。惟独恐其剥阳以为世道累，则不容于不去耳，而矜惜之意未尝不存，此和意也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>凡释卦名之后复有赞语者，皆以起释辞之端。此言“健而说，决而和”，起扬于王庭以下之意也。</p><p>扬于王庭，柔乘五刚也；孚号有厉，其危乃光也；告自邑不利即戎，所尚乃穷也；利有攸往，刚长乃终也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>此释卦辞。柔乘五刚，以卦体言，谓以一小人加于众君子之上，是其罪也。刚长乃终，谓一变即为纯干。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>柔虽消矣，然居五刚之上，犹为乘陵之象。阴而乘阳，非理之甚。君子势既足以去之，当显扬其罪于王朝大庭，使众知善恶也。尽诚信以命其众，而知有危惧，则君子之道乃无虞而光大也。当先自治，不宜专尚刚武，即戎则所尚乃至穷极矣。夬之时所尚谓刚武也。阳刚虽盛长，犹未终，尚有一阴，更当决去，则君子之道纯一而无害之者矣，乃刚长之终也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：刚克之道不可常行，若专用威猛，以此即戎，则便为尚力取胜，即是决而不和，其道穷矣。所以惟告自邑不利即戎者，只为所尚乃穷故也。</p></li><li><p>项氏安世曰 ：“其危乃光”与中“未光”相应，“不利即戎”与“暮夜有戎”相应，“刚长乃终”与“终有凶”相应。</p></li><li><p>胡氏炳文曰 ：复“利有攸往，刚长也”，夬“利有攸往，刚长乃终也”。小人有一人之未去，犹足为君子之忧；人欲有一分之未尽，犹足为天理之累。必至于纯阳为乾，方为刚长乃终也。</p></li><li><p>吴氏慎曰 ：复“利有攸往，刚长也”，譬如平地之一篑，故喜其进而曰“刚长也”。夬“利有攸往，刚长乃终也”，譬如九仞之尚亏一篑，故恐其止而曰“刚长乃终也”。</p></li></ul><p>初九：壮于前趾，往不胜为咎</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>前犹进也。当决之时，居下任壮，不胜宜矣。故其象占如此。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>九阳爻而干体刚健，在上之物乃在下而居决时，壮于前进者也。前趾谓进行，人之决于行也。行而宜，则其决为是；往而不宜，则决之过也。故往而不胜，则为咎也。夬之时而往往决也，故以胜负言。九居初而壮于进，躁于动者也，故有不胜之戒。阴虽将尽，而已之躁动，自宜有不胜之咎，不计彼也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>苏氏轼曰 ：大壮之长则为夬，故夬之初九与大壮之初九无异。</li></ul><p>苏氏轼曰 ：大壮之长则为夬，故夬之初九与大壮之初九无异。</p><ul><li>朱子语类云 ：壮于前趾与大壮初爻同，此卦大率似大壮，只争一画。</li></ul><p>朱子语类云 ：壮于前趾与大壮初爻同，此卦大率似大壮，只争一画。</p><ul><li>蔡氏清曰 ：其不胜者自为不胜也，故曰为咎，明非时势不利也。</li></ul><p>蔡氏清曰 ：其不胜者自为不胜也，故曰为咎，明非时势不利也。</p><p>象曰：不胜而往，咎也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>人之行，必度其事可为，然后决之，则无过矣。理不能胜而往，其咎可知。凡行而有咎者，皆决之过也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏申子曰：谓非往之为咎，不能度其可胜而后往之为咎也。</p></li><li><p>谷氏家杰曰：夬之道，其危乃光，胜心不可有也，况不胜而往乎？</p></li></ul><p>九二：惕号，莫夜有戎，勿恤</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>九二当决之时，刚而居柔，又得中道，故能忧惕号呼以自戒备，而莫夜有戎亦可无患也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>夬者，阳决阴，君子决小人之时，不可忘戒备也。阳长将极之时，而二处中居柔，不为过刚，能知戒备，处夬之至善也。内怀兢惕，而外严诚号，虽莫夜有兵戎，亦可勿恤矣。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>张子曰 ：警惧中号，能孚号而有厉也。以必胜之刚决至危之柔，能自危厉，虽有戎何恤？</li></ul><p>张子曰 ：警惧中号，能孚号而有厉也。以必胜之刚决至危之柔，能自危厉，虽有戎何恤？</p><ul><li>苏氏轼曰 ：莫夜警也，有戎勿恤静也。</li></ul><p>苏氏轼曰 ：莫夜警也，有戎勿恤静也。</p><ul><li>王氏中子曰 ：彖言孚号而以有厉处之矣。二刚得中而知戒惧，故亦惕号。盖必如是而后可免小人乘闲抵隙之忧，故虽莫夜阴伏之时，有兵戎亦不足虑矣。以防之密而备之素也。</li></ul><p>王氏中子曰 ：彖言孚号而以有厉处之矣。二刚得中而知戒惧，故亦惕号。盖必如是而后可免小人乘闲抵隙之忧，故虽莫夜阴伏之时，有兵戎亦不足虑矣。以防之密而备之素也。</p><ul><li>吴氏曰愼曰 ：刚中居柔，能忧惕号呼，即彖之“孚号有厉，告自邑不利即戎”者也。虽莫夜有戎而无忧。</li></ul><p>吴氏曰愼曰 ：刚中居柔，能忧惕号呼，即彖之“孚号有厉，告自邑不利即戎”者也。虽莫夜有戎而无忧。</p><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>此爻辞有以“惕号莫夜”为句，“有戎勿恤”为句者。言莫夜人所忽也，而犹惕号，则所以警惧者素矣；有戎人所畏也，而不之恤，则所以持重者至矣。盖即彖之所谓“孚号有厉，不利即戎”者也。夫惟无事而惕号，故有事而能勿恤。史称终日钦钦如对大敌，及临陈则志气安闲若不欲战者，是也。此卦当以九五为卦主，而彖辞之意独备于九二者，盖九二远阴，主于平时，则发“孚号告邑不利即戎”之义；九五近阴，主于临事，则发“扬于王庭利有攸往”之义。然其为中行中道，则一也。</p><p>象曰：有戎勿恤，得中道也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>莫夜有兵戎，可惧之甚也。然可勿恤者，以自处之善也。既得中道，又知惕惧，且有戒备，何事之足恤也？九居二虽得中，然非正，其为至善何也？曰阳决阴，君子决小人而得中，岂有不正也？知时识势，学易之大方也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰：能得中道，故刚而不暴。</p></li><li><p>苏氏轼曰：能静而不忘警，能警而不用，得中道矣。与大壮九二“贞吉”同，故皆称其得中。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>“有戎勿恤”者，谓不轻于即戎也，此所以为得中道。</p><p>九三：壮于頄，有凶。君子夬夬，独行遇雨，若濡，有愠无咎</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>頄，颧也。九三当决之时，以刚而过乎中，是欲决小人而刚壮见于面目也。如是则有凶道矣。然在众阳之中，独与上六为应，若能果决其决，不系私爱，则虽合于上六，如独行遇雨，至于若濡而为君子所愠，然终必能决去小人而无所咎也。温峤之于王敦，其事类此。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>爻辞差错安定，胡公移其文曰：“壮于頄有凶，独行遇雨，若濡，有愠，君子夬夬无咎。”亦未安也。当云：“壮于頄有凶，独行遇雨，君子夬夬，若濡，愠无咎。”夬决尚刚健之时，三居下体之上，又处健体之极，刚果于决者也。頄，颧骨也，在上而未极于上者也。三居下体之上，虽在上而未为最上，上有君而自任其刚决，壮于頄者也，有凶之道也。独行遇雨，三与上六为正应，方群阳共决一阴之时，已若以私应之，故不与众同而独行，则与上六阴阳和合，故云遇雨。易中言雨者，皆谓阴阳和也。君子道长，决去小人之时，而已独与之和，其非可知。唯君子处斯时，则能夬夬，谓夬其夬，果决其断也。虽其私与当远绝之，若见濡污，有愠恶之色，如此则无过咎也。三健体而处正，非必有是失也，因此义以为教耳。爻文所以交错者，由有遇雨字，又有濡字，故误以为连也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>陆氏希声曰 ：当君子之世而应小人，故外有沾污之累，内有愠恨之心，然后获无咎者，志存焉。</li></ul><p>陆氏希声曰 ：当君子之世而应小人，故外有沾污之累，内有愠恨之心，然后获无咎者，志存焉。</p><ul><li>王氏安石曰 ：九三干体之上，刚亢外见，壮于頄者也。夬夬者，必乎夬之辞也。应乎上六，疑于污也，故曰若濡。君子之所为，众人固不识。若濡，则有愠之者矣。和而不同，有夬夬之志焉，何咎之有？</li></ul><p>王氏安石曰 ：九三干体之上，刚亢外见，壮于頄者也。夬夬者，必乎夬之辞也。应乎上六，疑于污也，故曰若濡。君子之所为，众人固不识。若濡，则有愠之者矣。和而不同，有夬夬之志焉，何咎之有？</p><ul><li>郭氏雍曰 ：夬与大壮内卦三爻相类，故初九、九三言壮。壮者，小人用刚之事，非大者之壮也。二卦九三皆具君子小人二义，故大壮曰“小人用壮，君子用罔”，而此曰“壮于頄有凶，君子夬夬”。是也。以小人用壮言之，则知壮于頄者小人之事也，是以凶也。唯君子明夬夬之义，则终无咎矣。</li></ul><p>郭氏雍曰 ：夬与大壮内卦三爻相类，故初九、九三言壮。壮者，小人用刚之事，非大者之壮也。二卦九三皆具君子小人二义，故大壮曰“小人用壮，君子用罔”，而此曰“壮于頄有凶，君子夬夬”。是也。以小人用壮言之，则知壮于頄者小人之事也，是以凶也。唯君子明夬夬之义，则终无咎矣。</p><ul><li>朱子语类云 ：君子之去小人，不必悻悻然见于面目。至于遇雨而为所濡湿，虽为众阳所愠，然志在决阴，故得无咎也。盖九三虽与上六为应，而以刚居刚，有能决之象，故壮于頄则有凶，而和柔以去之乃无咎。</li></ul><p>朱子语类云 ：君子之去小人，不必悻悻然见于面目。至于遇雨而为所濡湿，虽为众阳所愠，然志在决阴，故得无咎也。盖九三虽与上六为应，而以刚居刚，有能决之象，故壮于頄则有凶，而和柔以去之乃无咎。</p><ul><li>蔡氏清曰 ：大意为君子之去小人，顾其本心何如耳。本心果是要决小人，则虽暂与之合而为善类之愠，终必能决之而无咎。不愈于壮于頄而有凶乎？此所以贵于决而和也。</li></ul><p>蔡氏清曰 ：大意为君子之去小人，顾其本心何如耳。本心果是要决小人，则虽暂与之合而为善类之愠，终必能决之而无咎。不愈于壮于頄而有凶乎？此所以贵于决而和也。</p><ul><li>何氏楷曰 ：上六为成兑之主，泽上于天，故称雨。以其适值而非本心也，故称遇。本非濡也，而迹类之，故称若。或观其迹而不察其心也，故称有“愠”。</li></ul><p>何氏楷曰 ：上六为成兑之主，泽上于天，故称雨。以其适值而非本心也，故称遇。本非濡也，而迹类之，故称若。或观其迹而不察其心也，故称有“愠”。</p><p>象曰：君子夬夬，终无咎也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>牵梏于私好，由无决也。君子义之与比，决于当决，故终不至于有咎也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>黄氏淳耀曰：终对始言之，始虽若濡有愠，终必决去而无咎也。</li></ul><p>九四：臀无肤，其行次且。牵羊悔亡，闻言不信</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>以阳居阴，不中不正，居则不安，行则不进。若不与众阳竞进而安出其后，则可以亡其悔。然当决之时，志在上进，必不能也。占者闻言而信，则转凶而吉矣。牵羊者，当其前则不进，纵之使前而随其后，则可以行矣。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>臀无肤，居不安也。行次且，进不前也。次且，进虽之状。九四以阳居阴，刚决不足，欲止则众阳并进于下，势不得安，犹臀伤而居不能安也。欲行则居柔失其刚壮，不能强进，故其行次且也。牵羊悔亡，羊者群行之物，牵者挽拽之义。言若能自强而牵挽以从群行，则可以亡其悔。然既处柔，必不能也。虽使闻是言，亦必不能信用也。夫过而能改，闻善而能用，克己以从义，唯刚明者能之。在它卦九居四，其失未至如此之甚。在夬而居柔，其害大矣。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>方氏应祥曰 ：牵羊之说，木义谓让羊使前而随其后，则羊乃众君子之象。若就兑羊之象言之，则羊还是九四。羊性善触，不至羸角不已。圣人教以自牵其羊，抑其很性，则可以亡悔矣。是亦壮頄有凶之意。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>臀者与阴相背之物也。夬四、姤三皆与阴连体而相背，故皆以臀为象。夫相背，则势犹和，远缓以处之可也。若臀有肤，则能安坐矣；臀无肤，喻四之不能安坐也。不能安坐，故次且而欲进。所以然者，不能自制其刚壮故也。苟能制其刚壮，如牵羊然，则可亡其悔。特恐当此时也，闻持重之言而不信耳。圣人于占戒之外，又设为反辞者，凡人有所忧畏瞻虑，则受警戒也。易时之可为，势之可乘，一则恐失事机，二则恐犯众议，是以闻言而多不信也。牵羊之说，方氏说善。</p><p>象曰：其行次且，位不当也；闻言不信，聪不明也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>九处阴位不当也，以阳居柔，失其刚决，故不能强进，其行次且。刚然后能明，处柔则迁失其正性，岂复有明也？故闻言而不能信者，盖其聪听之不明也。</p><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>四与阴尚隔，位不当者，借爻位以明四之未当事任，而欲次且前进之非宜也。</p><p>九五：苋陆夬夬，中行无咎</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>苋陆，今马齿苋，感阴气之多者。九五当决之时，为决之主而切近上六之阴，如苋陆然。若决而决之，而又不为过暴，合于中行，则无咎矣。戒占者当如是也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>五虽刚阳中正，居尊位，然切近于上六。上六说体，而卦独一阴，阳之所比也。五为决阴之主，而反比之，其咎大矣。故必决其决，如苋陆然，则于其中行之德为无咎也。中行，中道也。苋陆，今所谓马齿苋是也，曝之难干，感阴气之多者也，而脆易折。五若如苋陆，虽感于阴而决断之易，则于中行无过咎矣。不然，则失其中正也。感阴多之物，苋陆为易断，故取为象。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>郑氏汝谐曰 ：苋陆，《本草》云一名商陆，其根至蔓虽尽取之而旁根复生，小人之类难绝如此。</li></ul><p>郑氏汝谐曰 ：苋陆，《本草》云一名商陆，其根至蔓虽尽取之而旁根复生，小人之类难绝如此。</p><ul><li>朱子语类云 ：苋陆是两物，苋者马齿苋，陆者草陆，一名商陆，皆感阴气多之物。药中用商陆治水肿，其物难干，其子红。</li></ul><p>朱子语类云 ：苋陆是两物，苋者马齿苋，陆者草陆，一名商陆，皆感阴气多之物。药中用商陆治水肿，其物难干，其子红。</p><ul><li>项氏安世曰 ：夬夬者，重夬也。当夬者上六也，三应之，五比之。嫌其不能夬也，故皆以夬夬明之。三谓之遇雨，五谓之苋陆，皆与阴俱行者也。比于阴而能自决以保其中，故可免咎。案此言苋陆夬夬，犹姤言包瓜，皆以细草阴类喻小人也。时当含章则包之，时当扬庭则决之。然其包之也，以杞刚之体不失也；其决之也，以中行柔之用兼济也。</li></ul><p>项氏安世曰 ：夬夬者，重夬也。当夬者上六也，三应之，五比之。嫌其不能夬也，故皆以夬夬明之。三谓之遇雨，五谓之苋陆，皆与阴俱行者也。比于阴而能自决以保其中，故可免咎。案此言苋陆夬夬，犹姤言包瓜，皆以细草阴类喻小人也。时当含章则包之，时当扬庭则决之。然其包之也，以杞刚之体不失也；其决之也，以中行柔之用兼济也。</p><p>象曰：中行无咎，中未光也</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>程传备矣。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>卦辞言“夬夬”，则于中行为无咎矣。象复尽其义，云“中未光也”。夫人心正意诚，乃能极中正之道而充实光辉。五心有所比，以义之不可而决之，虽行于外，不失中正之义，可以无咎。然于中道未得为光大也。盖人心一有所欲，则离道矣。夫子于此示人之意深矣。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰：阳近于阴，不能无累，故必正其行然后免咎。</p></li><li><p>赵氏汝梅曰：他卦贵于中行，此爻乃止于无咎，其亦体兑之说溺于上而致然乎？故于中为未光也。</p></li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>张子之说极是。盖因中未光，故贵于中行，非谓虽中行而犹未光也。</p><p>上六：无号，终有凶</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>阴柔小人居穷极之时，党类已尽，无所号呼，终必有凶也。占者有君子之德，则其敌当之，不然反是。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>阳长将极，阴消将尽，独一阴处穷极之地，是众君子得时决去危极之小人也。其势必须消尽，故云无用号啕畏惧，终必有凶也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>苏氏轼曰 ：无号者，不警也。阳不警，则有以乘之矣。</li></ul><p>苏氏轼曰 ：无号者，不警也。阳不警，则有以乘之矣。</p><ul><li>杨氏简曰 ：柔已决去，刚道已长，然不可不敬戒。苟忽焉不敬不戒，不警号，则亦终有凶。虽未必凶遂至，而既不警戒，则放逸，逸则失道矣。失道者终于凶。</li></ul><p>杨氏简曰 ：柔已决去，刚道已长，然不可不敬戒。苟忽焉不敬不戒，不警号，则亦终有凶。虽未必凶遂至，而既不警戒，则放逸，逸则失道矣。失道者终于凶。</p><ul><li>蒋氏悌生曰 ：《易》为君子谋，不为小人谋。详味此爻，若如传义说，似为小人谋。恐只依卦辞“孚号有厉”之意言，虽是五阳决去一阴，尚存为君子之计。苟或黙然养祸，则其终必致凶。圣人之情，何当虑小人凶也。</li></ul><p>蒋氏悌生曰 ：《易》为君子谋，不为小人谋。详味此爻，若如传义说，似为小人谋。恐只依卦辞“孚号有厉”之意言，虽是五阳决去一阴，尚存为君子之计。苟或黙然养祸，则其终必致凶。圣人之情，何当虑小人凶也。</p><p>总论</p><ul><li>徐氏几曰：夬决也，以盛进之五刚决衰退之一柔，其势若甚易。然而圣人不敢以易而忽之，故于夬之一卦丁宁深切，所以周防戒备者无所不至。</li></ul><p>徐氏几曰：夬决也，以盛进之五刚决衰退之一柔，其势若甚易。然而圣人不敢以易而忽之，故于夬之一卦丁宁深切，所以周防戒备者无所不至。</p><ul><li>龚氏焕曰：夬卦似大壮，故诸爻多与大壮相似。初之壮于趾，三之壮于頄之类是也。夬以五阳决一阴，其壮甚矣。圣人虑其夬决之过，故于爻皆致戒，而以阳居阳者为尤甚焉。阳之决阴，君子之去小人，亦贵乎中而已矣。</li></ul><p>龚氏焕曰：夬卦似大壮，故诸爻多与大壮相似。初之壮于趾，三之壮于頄之类是也。夬以五阳决一阴，其壮甚矣。圣人虑其夬决之过，故于爻皆致戒，而以阳居阳者为尤甚焉。阳之决阴，君子之去小人，亦贵乎中而已矣。</p><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>夬之与壮，前三爻全相类是已，后三爻先儒未详说。须知壮之当前者四也，夬之当前者五也。故壮四之藩决，即夬五之夬。夬若壮之六五，则壮已过而非用壮之时；夬之九四，则夬未及而亦未可为果决之事。故壮五之丧羊，即夬四之牵羊也。若壮上之艰，夬上之号，则戒之始终不忘危惧而已。壮不如夬之盛，故犹曰不能遂；夬则可以遂矣，然其危惧之心同也。</p><p>象曰：无号之凶，终不可长也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>阳刚君子之道，进而益盛，小人之道既已穷极，自然消亡，岂复能长久乎？虽号啕无以为也，故云终不可长也。先儒以卦中有“孚号惕”，号欲以“无号”为无号作去声，谓无用更加号令，非也。一卦中适有两去声字，一平声字，何害而读易者率皆疑之？或曰：“圣人之于天下，虽大恶未尝必绝之也。今直使之无号，谓必有凶可乎？”曰：“夬者，小人之道消亡之时也。决去小人之道，岂必尽诛之乎？使之变革，乃小人之道亡也，道亡乃其凶也。”</p>',156)])])}const u=l(h,[["render",p]]);export{b as __pageData,u as default};
